#include "document.h"
#include "project_encode.h"
#include "project_import.h"
#include <iostream>
using namespace moon;
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
int main(){try{Document d(32,32);d.beginStroke({1,1},0xff123456);d.commitStroke();d.undo();d.markSaved();CHECK(d.canRedo());const auto layers=d.timeline().state().layers.size();auto data=newTextToolData(0xff443322);data.text=u"A😀中\nB";data.boxed=true;data.originX=-3;data.originY=4;data.boxWidth=12;data.boxHeight=18;data.styleRuns={{1,3,17,{},{},0xff998877}};data.transforms={{{-3,4,12,18},{-2,5,14,20},15,{}}};timeline::Surface s{2,2,-3,4,{},{},{0xff443322,0,0,0xff443322}};CHECK(d.beginTextDraft(data,s));CHECK(d.active()&&!d.dirty());d.cancelTextDraft();CHECK(d.canRedo()&&d.timeline().state().layers.size()==layers&&!d.dirty());CHECK(d.beginTextDraft(data,s));CHECK(d.commitTextDraft());const auto id=d.cel().id;CHECK(d.layer().kind=="text"&&!d.rasterToolsAvailable());const auto count=d.historySize();auto updated=data;updated.text=u"Changed😀";CHECK(d.beginTextDraft(updated,s,id));d.cancelTextDraft();CHECK(d.cel().text->text==data.text&&d.historySize()==count);CHECK(d.beginTextDraft(updated,s,id));CHECK(d.commitTextDraft());d.undo();CHECK(d.cel().text->text==data.text);d.redo();CHECK(d.cel().text->text==updated.text);CHECK(d.beginLayerMove({id}));CHECK(d.previewLayerMove(7,-2));CHECK(d.cel().text->originX==4);CHECK(d.commitLayerMove());d.undo();CHECK(d.cel().text->originX==-3);d.redo();CHECK(d.cel().text->originY==2);auto encoded=project::encodeEditableProject(d);auto manifest=project::readProjectManifest(encoded.bytes);auto imported=project::prepareEditableImport(manifest);auto cel=std::find_if(imported.timeline.cels.begin(),imported.timeline.cels.end(),[&](const auto& c){return c.id==id;});CHECK(cel!=imported.timeline.cels.end()&&cel->text&&cel->text->text==updated.text&&cel->text->originX==4&&cel->text->transforms.size()==1);CHECK(cel->text->styleRuns[0].start==1&&cel->text->styleRuns[0].end==3);std::cout<<"Text draft/cancel/history/move/project roundtrip passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
